add(31, ru=("Водитель на шоссе обязан уступить", "любой машине, выезжающей со двора", "пешеходу", "машинам, подъезжающим к перекрёстку слева"), es=("El conductor en una autopista debe ceder el paso a", "cualquier auto que sale de una entrada", "un peatón", "autos que se acercan a un cruce desde la izquierda"), pt=("O motorista numa rodovia deve ceder a", "qualquer carro saindo de uma entrada", "um pedestre", "carros que se aproximam de um cruzamento pela esquerda"), fr=("Le conducteur sur une route doit céder le passage", "à toute voiture sortant d'une allée", "à un piéton", "aux voitures arrivant d'un carrefour par la gauche"), de=("Der Fahrer auf einer Straße muss Vorfahrt gewähren", "jedem Auto aus einer Einfahrt", "einem Fußgänger", "Autos, die von links an eine Kreuzung kommen"))
add(32, ru=("Собираясь повернуть налево, уступите встречным машинам", "пока не проедут хотя бы две", "которые достаточно близко и опасны", "пока не проедут пять машин"), es=("Al ir a girar a la izquierda, cede el paso a los que vienen de frente", "hasta que pasen al menos dos autos", "que estén lo bastante cerca para ser peligrosos", "hasta que pasen cinco autos"), pt=("Ao virar à esquerda, ceda a passagem aos que vêm em sentido contrário", "até passarem pelo menos dois carros", "que estejam perto o bastante para ser perigosos", "até passarem cinco carros"), fr=("Avant de tourner à gauche, cédez aux voitures d'en face", "jusqu'à ce qu'au moins deux soient passées", "assez proches pour être dangereuses", "jusqu'à ce que cinq soient passées"), de=("Vor dem Linksabbiegen gewähren Sie entgegenkommenden Autos Vorfahrt", "bis mindestens zwei vorbei sind", "die nah genug und gefährlich sind", "bis fünf Autos vorbei sind"))
add(33, ru=("Если на школьном переходе есть пешеходы, вы обязаны", "остановиться и пропустить только тех, кто идёт справа", "остановиться только ради детей и пропустить их", "остановиться и не ехать, пока все полностью не сойдут с перехода"), es=("Si hay peatones en un cruce escolar, debes", "parar y ceder solo a quienes cruzan desde tu derecha", "parar solo por los niños y cederles el paso", "parar y no seguir hasta que todos hayan salido del cruce"), pt=("Se há pedestres na faixa escolar, você deve", "parar e ceder só a quem cruza pela sua direita", "parar só para crianças e ceder a elas", "parar e não seguir até todos saírem completamente da faixa"), fr=("S'il y a des piétons sur un passage scolaire, vous devez", "vous arrêter seulement pour ceux qui viennent de votre droite", "vous arrêter seulement pour les enfants", "vous arrêter et ne pas repartir tant que tous n'ont pas quitté le passage"), de=("Sind Fußgänger auf einem Schulübergang, müssen Sie", "nur anhalten für Personen von rechts", "nur für Kinder anhalten und sie durchlassen", "anhalten und erst weiterfahren, wenn alle den Übergang verlassen haben"))
add(34, ru=("Должен ли поворачивающий водитель уступать пешеходам?", "да, при повороте направо или налево нужно уступать пешеходам", "нет, пешеходы должны уступать всем машинам", "да, но только если водитель поворачивает налево"), es=("¿Debe ceder el paso a los peatones un conductor que gira?", "sí, al girar a la derecha o a la izquierda debe ceder a los peatones", "no, los peatones deben ceder a todos los vehículos", "sí, pero solo si gira a la izquierda"), pt=("Um motorista que vira deve ceder a passagem aos pedestres?", "sim, ao virar à direita ou à esquerda deve ceder aos pedestres", "não, os pedestres devem ceder a todos os veículos", "sim, mas só se estiver virando à esquerda"), fr=("Un conducteur qui tourne doit-il céder aux piétons ?", "oui, en tournant à droite ou à gauche il doit céder aux piétons", "non, les piétons doivent céder à tous les véhicules", "oui, mais seulement s'il tourne à gauche"), de=("Muss ein abbiegender Fahrer Fußgängern Vorfahrt gewähren?", "ja, beim Rechts- oder Linksabbiegen muss er Fußgängern Vorfahrt gewähren", "nein, Fußgänger müssen allen Fahrzeugen Vorfahrt gewähren", "ja, aber nur beim Linksabbiegen"))
add(35, ru=("На улице с двусторонним движением вы слышите сирену спецмашины. Что требует закон?", "принять вправо и остановиться", "ускориться, чтобы уйти с дороги", "продолжать на высокой скорости"), es=("En una calle de doble sentido oyes la sirena de un vehículo de emergencia. ¿Qué exige la ley?", "orillarte a la derecha y detenerte", "acelerar para quitarte del camino", "seguir a alta velocidad"), pt=("Numa rua de mão dupla você ouve a sirene de um veículo de emergência. O que a lei exige?", "encostar à direita e parar", "acelerar para sair do caminho", "continuar em alta velocidade"), fr=("Dans une rue à double sens, vous entendez une sirène. Que dit la loi ?", "se ranger à droite et s'arrêter", "accélérer pour dégager", "continuer à grande vitesse"), de=("Auf einer Gegenverkehrsstraße hören Sie ein Einsatzhorn. Was verlangt das Gesetz?", "nach rechts fahren und anhalten", "beschleunigen, um aus dem Weg zu kommen", "mit hoher Geschwindigkeit weiterfahren"))
add(36, ru=("Две машины встретились на подъёме, где ни одна не может проехать. Кто уступает?", "та, что смотрит под гору", "та, что смотрит в гору", "та, что первой посигналит"), es=("Dos vehículos se encuentran en una subida donde ninguno puede pasar. ¿Quién cede?", "el que mira cuesta abajo", "el que mira cuesta arriba", "el que toca primero la bocina"), pt=("Dois veículos se encontram numa subida onde nenhum consegue passar. Quem cede?", "o que está de frente para a descida", "o que está de frente para a subida", "o que buzinar primeiro"), fr=("Deux véhicules se croisent en montée et aucun ne peut passer. Qui cède ?", "celui qui fait face à la descente", "celui qui fait face à la montée", "celui qui klaxonne le premier"), de=("Zwei Fahrzeuge treffen sich an einer Steigung, wo keines vorbeikommt. Wer muss weichen?", "das bergab schauende", "das bergauf schauende", "das, das zuerst hupt"))
add(37, ru=("Перед перестроением всегда подайте сигнал, посмотрите в зеркало и", "поверните голову, чтобы увидеть машины рядом", "посигнальте", "моргните фарами"), es=("Antes de cambiar de carril, señaliza, mira el retrovisor y", "gira la cabeza para ver los vehículos a tu lado", "toca la bocina", "haz un destello con las luces"), pt=("Antes de mudar de faixa, sinalize, olhe o retrovisor e", "vire a cabeça para ver os veículos ao lado", "buze", "pisque o farol"), fr=("Avant de changer de voie, signalez, vérifiez le rétroviseur et", "tournez la tête pour voir les véhicules à côté", "klaxonnez", "faites un appel de phares"), de=("Vor dem Spurwechsel immer blinken, in den Spiegel schauen und", "den Kopf drehen, um Fahrzeuge neben Ihnen zu sehen", "hupen", "aufblenden"))
add(38, ru=("Перестраиваться можно только после того, как вы", "показали намерение и проверили движение", "показали намерение", "проверили движение"), es=("Cambia de carril solo después de", "señalizar tu intención y revisar el tráfico", "señalizar tu intención", "revisar el tráfico"), pt=("Mude de faixa só depois de", "sinalizar a intenção e checar o tráfego", "sinalizar a intenção", "checar o tráfego"), fr=("Ne changez de voie qu'après avoir", "signalé votre intention et vérifié la circulation", "signalé votre intention", "vérifié la circulation"), de=("Wechseln Sie die Spur erst, nachdem Sie", "die Absicht angezeigt und den Verkehr geprüft haben", "die Absicht angezeigt haben", "den Verkehr geprüft haben"))
add(39, ru=("После обгона можно вернуться в свою полосу, если", "водитель, которого вы обогнали, сигналит", "в зеркале заднего вида видна обогнанная машина", "в боковом зеркале видна обогнанная машина"), es=("Tras adelantar puedes volver a tu carril si", "el conductor adelantado toca la bocina", "ves en el retrovisor el auto que adelantaste", "ves en el espejo lateral el auto que adelantaste"), pt=("Depois de ultrapassar, você pode voltar à faixa se", "o motorista ultrapassado buzinar", "você vir no retrovisor o carro ultrapassado", "você vir no espelho lateral o carro ultrapassado"), fr=("Après un dépassement, vous pouvez revenir si", "le conducteur dépassé klaxonne", "vous voyez dans le rétroviseur la voiture dépassée", "vous la voyez dans le rétroviseur latéral"), de=("Nach dem Überholen dürfen Sie zurück, wenn", "der Überholte hupt", "Sie das überholte Auto im Rückspiegel sehen", "Sie es im Seitenspiegel sehen"))
add(40, ru=("Можно обгонять справа машину, едущую в ту же сторону", "если дорога явно размечена на две или больше полос в одну сторону", "на дороге с одной полосой во встречном направлении", "съехав с проезжей части"), es=("Puedes adelantar por la derecha a un auto que va en tu dirección", "si la vía está marcada con dos o más carriles en el mismo sentido", "en una vía con un carril en sentido contrario", "saliéndote del pavimento"), pt=("Você pode ultrapassar pela direita um carro no mesmo sentido", "se a via estiver marcada com duas ou mais faixas no mesmo sentido", "numa via com uma faixa no sentido contrário", "saindo do pavimento"), fr=("Vous pouvez dépasser par la droite une voiture dans votre sens", "si la route a clairement deux voies ou plus dans le même sens", "sur une route à une voie en sens inverse", "en quittant la chaussée"), de=("Sie dürfen rechts überholen, wenn das Auto in Ihre Richtung fährt", "wenn die Straße klar zwei oder mehr Spuren in dieselbe Richtung hat", "auf einer Straße mit einer Spur in Gegenrichtung", "indem Sie die Fahrbahn verlassen"))
add(41, ru=("Если вы в неверной полосе, что сделать, чтобы повернуть на перекрёстке?", "повернуть как можно быстрее", "тормозить или выжимать сцепление уже в повороте", "посмотреть назад с обеих сторон и убедиться, что смена полосы безопасна"), es=("Si vas en el carril equivocado, ¿qué debes hacer para girar al entrar al cruce?", "girar lo más rápido posible", "frenar o pisar el embrague mientras giras", "mirar atrás a ambos lados y ver si es seguro cambiar de carril"), pt=("Se você está na faixa errada, o que fazer para virar ao entrar no cruzamento?", "virar o mais rápido possível", "frear ou pisar na embreagem durante a curva", "olhar para trás dos dois lados e ver se é seguro mudar de faixa"), fr=("Si vous êtes sur la mauvaise voie, que faire pour tourner en entrant dans le carrefour ?", "tourner le plus vite possible", "freiner ou débrayer pendant le virage", "regarder derrière des deux côtés et changer de voie seulement si c'est sûr"), de=("Wenn Sie auf der falschen Spur sind: Was tun, um an der Kreuzung abzubiegen?", "so schnell wie möglich abbiegen", "während des Abbiegens bremsen oder kuppeln", "nach hinten auf beide Seiten schauen und nur wechseln, wenn es sicher ist"))
add(42, ru=("Сигнал поворота направо или налево нужно начать не менее чем за", "30 метров", "60 метров", "15 метров"), es=("Debes empezar a señalizar un giro a la derecha o a la izquierda al menos", "30 metros antes", "60 metros antes", "15 metros antes"), pt=("Você deve começar a sinalizar uma curva à direita ou à esquerda pelo menos", "30 metros antes", "60 metros antes", "15 metros antes"), fr=("Commencez à signaler un virage à droite ou à gauche au moins", "30 mètres avant", "60 mètres avant", "15 mètres avant"), de=("Blinken Sie für links oder rechts mindestens", "30 Meter vorher", "60 Meter vorher", "15 Meter vorher"))
add(43, ru=("Поворот направо обычно начинают из", "полосы ближе к центру дороги", "полосы ближе к правому бордюру", "той же полосы, что и для поворота налево"), es=("Normalmente empiezas un giro a la derecha desde", "el carril más cercano al centro", "el carril más cercano al bordillo derecho", "el mismo carril que para girar a la izquierda"), pt=("Normalmente você começa uma curva à direita na", "faixa mais perto do centro da via", "faixa mais perto do meio-fio direito", "mesma faixa usada para virar à esquerda"), fr=("Vous commencez normalement un virage à droite depuis", "la voie la plus proche du centre", "la voie la plus proche du trottoir droit", "la même voie que pour tourner à gauche"), de=("Rechtsabbiegen beginnen Sie normalerweise auf", "der Spur näher zur Straßenmitte", "der Spur am rechten Bordstein", "derselben Spur wie beim Linksabbiegen"))
add(44, ru=("Машина сзади хочет вас обогнать. Вам следует", "посигналить, чтобы он проехал", "немного замедлиться и принять вправо", "принять вправо и остановиться, чтобы он проехал"), es=("El auto de atrás quiere adelantarte. Debes", "tocar la bocina para dejarlo pasar", "reducir un poco y orillarte a la derecha", "orillarte a la derecha y parar para que pase"), pt=("O carro atrás quer ultrapassar. Você deve", "buzinar para deixá-lo passar", "reduzir um pouco e ir para a direita", "ir para a direita e parar para ele passar"), fr=("La voiture derrière veut vous dépasser. Vous devriez", "klaxonner pour la laisser passer", "ralentir un peu et vous déporter à droite", "vous ranger à droite et vous arrêter pour qu'elle passe"), de=("Das Auto hinter Ihnen will überholen. Sie sollten", "hupen, damit es vorbeifährt", "etwas langsamer werden und nach rechts ziehen", "nach rechts fahren und anhalten, damit es vorbeikann"))
add(45, ru=("Ночью на шоссе ближний свет нужно включать, когда", "встречный водитель переключился на ближний", "вас ослепляют фары встречной машины", "всё перечисленное"), es=("De noche en carretera usa las luces bajas cuando", "otro conductor baja sus luces", "te deslumbran los faros de un vehículo que se acerca", "todo lo anterior"), pt=("À noite na estrada, use farol baixo quando", "outro motorista baixar o farol", "você for ofuscado pelos faróis de quem vem em sentido contrário", "todas as anteriores"), fr=("La nuit sur route, utilisez les feux de croisement quand", "un autre conducteur baisse ses feux", "vous êtes ébloui par un véhicule en face", "tout ce qui précède"), de=("Nachts auf der Straße Abblendlicht verwenden, wenn", "ein anderer Fahrer abblendet", "Sie vom Gegenverkehr geblendet werden", "alles davon"))
add(46, ru=("Если у нескольких машин впереди загорелись стоп-сигналы, нужно", "отпустить газ и приготовиться тормозить", "сразу нажать тормоз", "увеличить скорость"), es=("Si se encienden las luces de freno de varios autos adelante, debes", "soltar el acelerador y prepararte para frenar", "frenar lo antes posible", "aumentar la velocidad"), pt=("Se as luzes de freio de vários carros à frente acenderem, você deve", "soltar o acelerador e se preparar para frear", "frear o quanto antes", "aumentar a velocidade"), fr=("Si les feux stop de plusieurs voitures devant s'allument, vous devez", "lâcher l'accélérateur et vous préparer à freiner", "freiner dès que possible", "accélérer"), de=("Wenn vor Ihnen bei mehreren Autos die Bremslichter aufleuchten, sollten Sie", "vom Gas gehen und bremsbereit sein", "sofort bremsen", "schneller werden"))
add(47, ru=("Что из этого неправильно при повороте направо?", "остановиться на пешеходном переходе", "подать сигнал не менее чем за 30 метров", "смотреть, нет ли пешеходов на улице, куда вы въезжаете"), es=("¿Cuál de estos pasos no es correcto al girar a la derecha?", "detenerse en el paso de peatones", "señalizar al menos 30 metros antes", "vigilar a los peatones en la calle a la que vas a entrar"), pt=("Qual destes passos não é correto ao virar à direita?", "parar na faixa de pedestres", "sinalizar pelo menos 30 metros antes", "observar pedestres na rua em que você vai entrar"), fr=("Laquelle de ces étapes est incorrecte pour tourner à droite ?", "s'arrêter sur le passage piéton", "signaler au moins 30 mètres avant", "surveiller les piétons dans la rue où vous entrez"), de=("Welcher Schritt ist beim Rechtsabbiegen falsch?", "auf dem Fußgängerüberweg anhalten", "mindestens 30 Meter vorher blinken", "auf Fußgänger in der Straße achten, in die Sie einbiegen"))
add(48, ru=("Нельзя обгонять у начала или на подходе к мосту, потому что", "не видно встречных машин с другой стороны моста", "там переходят пешеходы", "можно помешать потоку"), es=("No debes adelantar al pie o a la entrada de un puente porque", "no ves los vehículos que vienen del otro lado", "hay peatones cruzando", "podrías obstruir el tráfico"), pt=("Não se deve ultrapassar no pé ou na aproximação de uma ponte porque", "não se vê os veículos que vêm do outro lado", "há pedestres atravessando", "você pode atrapalhar o fluxo"), fr=("Il ne faut pas dépasser au pied ou à l'approche d'un pont parce que", "on ne voit pas les véhicules venant de l'autre côté", "des piétons traversent", "on pourrait gêner le flot"), de=("Am Fuß oder vor einer Brücke darf man nicht überholen, weil", "man den Gegenverkehr von der anderen Seite nicht sieht", "Fußgänger überqueren", "man den Verkehr behindern könnte"))
add(49, ru=("Лучше всего при повороте на шоссе", "показать сигнал уже в момент поворота", "подать световой и/или сигнал рукой не менее чем за 30 метров", "не сигналить, если впереди и сзади никого нет"), es=("La mejor práctica al girar en carretera es", "señalizar justo al girar", "dar señal eléctrica y/o manual al menos 30 metros antes", "no señalizar si no hay tráfico delante ni detrás"), pt=("A melhor prática ao virar numa rodovia é", "sinalizar no momento da curva", "dar sinal elétrico e/ou manual pelo menos 30 metros antes", "não sinalizar se não houver tráfego à frente nem atrás"), fr=("La meilleure pratique pour tourner sur route est", "de signaler au moment du virage", "de donner un clignotant et/ou un geste au moins 30 mètres avant", "de ne pas signaler s'il n'y a personne devant ni derrière"), de=("Am besten biegen Sie auf der Straße ab, indem Sie", "erst beim Abbiegen blinken", "mindestens 30 Meter vorher Blinker und/oder Handzeichen geben", "nicht blinken, wenn niemand vor oder hinter Ihnen ist"))
add(50, ru=("Обгонять по обочине справа машину впереди", "можно, если вы поворачиваете направо", "можно, если машина впереди поворачивает налево", "запрещено законом"), es=("Usar el arcén para pasar por la derecha a un auto adelante", "está permitido si vas a girar a la derecha", "está permitido si el auto de adelante gira a la izquierda", "va contra la ley"), pt=("Usar o acostamento para passar pela direita de um carro à frente", "é permitido se você vai virar à direita", "é permitido se o carro da frente vai virar à esquerda", "é contra a lei"), fr=("Dépasser par l'accotement à droite d'une voiture devant", "est permis si vous tournez à droite", "est permis si la voiture devant tourne à gauche", "est interdit par la loi"), de=("Rechts über den Seitenstreifen an einem Auto vorbeizufahren ist", "erlaubt, wenn Sie rechts abbiegen", "erlaubt, wenn das Auto vor Ihnen links abbiegt", "gesetzlich verboten"))
